std::string decoded;
std::shared_ptr<Node> current = root;
int bits_read = 0;
unsigned char byte;
while (infile.read(reinterpret_cast<char*>(&byte), sizeof(byte)) && bits_read < encoded_length) {
    for (int bit_idx = 7; bit_idx >= 0 && bits_read < encoded_length; --bit_idx) {
        bool bit = (byte >> bit_idx) & 1;
        if (bit) {
            current = current->right;
        } else {
            current = current->left;
        }
        if (!current->left && !current->right) {
            decoded += current->character;
            current = root;
        }
        ++bits_read;
    }
}
return decoded;

